import{_ as t,o as i,c as s,a6 as a}from"./chunks/framework.Dtv7txdI.js";const p=JSON.parse('{"title":"Security & the Sandbox","description":"","frontmatter":{},"headers":[],"relativePath":"v1/server/security.md","filePath":"v1/server/security.md","lastUpdated":1787648967000}'),o={name:"v1/server/security.md"};function n(r,e,d,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="security-the-sandbox" tabindex="-1">Security &amp; the Sandbox <a class="header-anchor" href="#security-the-sandbox" aria-label="Permalink to “Security &amp; the Sandbox”">​</a></h1><p>Nitr&#39;s pitch is <em>semi-trusted logic with explicit boundaries</em>: application Lua is assumed to be <strong>buggy, not hostile</strong> — but the sandbox is built so that most classes of hostile script fail anyway.</p><p>This page states where those boundaries actually are. The honest version is more useful than a reassuring one.</p><h2 id="what-the-sandbox-defends-against" tabindex="-1">What the sandbox defends against <a class="header-anchor" href="#what-the-sandbox-defends-against" aria-label="Permalink to “What the sandbox defends against”">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Defense</th></tr></thead><tbody><tr><td><strong>CPU exhaustion</strong> (<code>while true do end</code>)</td><td>A per-request execution budget enforced by an instruction-count hook installed globally on the state — user coroutines inherit it — plus an async timeout for slow I/O.</td></tr><tr><td><strong>Memory exhaustion</strong></td><td>A per-state Lua memory limit (8 MiB by default). A state that hits it is poisoned, dropped and rebuilt; it never serves another request.</td></tr><tr><td><strong>Filesystem / process access from Lua</strong></td><td><code>io</code> and <code>os</code> are excluded from the stdlib by default, and nothing in <code>nitr.*</code> needs them (<code>nitr.time</code> covers dates, <code>nitr.path</code> is lexical only). Native Lua modules cannot be loaded, and <code>require</code> is confined to the handler script&#39;s directory.</td></tr><tr><td><strong>Request-smuggling-sized inputs</strong></td><td>Rust-enforced limits <em>before</em> Lua runs: URI, headers, body (counted as it arrives, not trusted from <code>Content-Length</code>), form parts, field and file sizes, connection cap, per-IP rate limit.</td></tr><tr><td><strong>SSRF from <code>nitr.fetch</code></strong></td><td>Private, loopback, link-local and CGNAT ranges refused by default. The filtering happens <strong>inside the resolver the connector uses</strong>, so DNS rebinding does not bypass it; every redirect hop is re-checked; a per-request outbound budget caps the blast radius.</td></tr><tr><td><strong>Path traversal out of static mounts</strong></td><td>Percent-decode → component whitelist → canonicalize-prefix check, symlinks included. <code>nitr.path.normalize</code> cannot be climbed with <code>..</code>. Both are fuzzed.</td></tr><tr><td><strong>Cross-state data leakage</strong></td><td>Pooled states share nothing Lua-visible. The shared cache and the config snapshot carry plain serialized data only — never live Lua values.</td></tr><tr><td><strong>Forged cookies, sessions and tokens</strong></td><td>HMAC-SHA256 signatures with constant-time verification, and the cookie name bound into the MAC. JWT verification requires an explicit algorithm allow-list and structurally cannot accept <code>alg: none</code>.</td></tr><tr><td><strong>A wedged or draining instance receiving traffic</strong></td><td>Rust-owned <code>/readyz</code> flips <em>before</em> requests can fail. An application cannot report itself healthy through a broken handler.</td></tr><tr><td><strong>Damaged states after a panic or memory hit</strong></td><td>Per-request <code>catch_unwind</code>. Poisoned states are recycled, not reused.</td></tr></tbody></table><h2 id="what-it-does-not-defend-against" tabindex="-1">What it does not defend against <a class="header-anchor" href="#what-it-does-not-defend-against" aria-label="Permalink to “What it does not defend against”">​</a></h2><p>Stated plainly, because a boundary you do not know about is not a boundary.</p><ul><li><strong>A malicious Rust extension module.</strong> <code>ServerBuilder::module</code> code is unsandboxed by design — it <em>is</em> your process. The sandbox is for Lua.</li><li><strong>OS-level resource exhaustion</strong>: file descriptors, disk space, kernel memory. Run Nitr under a supervisor with OS limits — see the <a href="./deployment/systemd">systemd unit</a> for hardened settings.</li><li><strong>Side channels between states</strong> — timing, cache effects, and inference from shared-cache hit patterns.</li><li><strong>A Lua VM escape</strong> through a vulnerability in Lua 5.4 or mlua. The sandbox narrows the attack surface (no <code>io</code>/<code>os</code>, no native loading); it does not patch the VM.</li><li><strong>Denial of service by a legitimate key.</strong> The rate limiter is per-client-IP and fixed-window; a distributed attacker, or one behind a shared NAT, is bounded only by the connection and pool limits.</li></ul><h2 id="known-weaknesses" tabindex="-1">Known weaknesses <a class="header-anchor" href="#known-weaknesses" aria-label="Permalink to “Known weaknesses”">​</a></h2><p>Tracked deliberately rather than glossed over:</p><ul><li><strong>The rate limiter is a fixed window</strong>, so bursts straddling a window boundary can briefly reach twice the intended rate. A sliding-window revisit is parked, not forgotten.</li><li><strong>Sessions cannot be invalidated server-side</strong> before their cookie expires. That is the documented cost of stateless sessions; rotating the secret invalidates everything at once. See <a href="./cookies-sessions#what-a-stateless-session-means">Sessions</a>.</li><li><strong>There is no metrics endpoint yet</strong>, so abuse is visible in logs but not on a dashboard.</li></ul><h2 id="the-sandbox-settings" tabindex="-1">The sandbox settings <a class="header-anchor" href="#the-sandbox-settings" aria-label="Permalink to “The sandbox settings”">​</a></h2><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lua</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stdlib = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;math&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;table&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;utf8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;coroutine&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory_limit = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8388608</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # bytes, per state</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">exec_timeout_ms = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 0 disables the execution budget</span></span></code></pre></div><div class="danger custom-block github-alert"><p class="custom-block-title">Adding `io` or `os` is a deliberate reduction of the sandbox</p><p></p><p>With <code>os</code> come <code>os.execute</code>, <code>os.remove</code> and <code>os.getenv</code>. With <code>io</code> comes arbitrary file access. Nothing in <code>nitr.*</code> needs either — <code>nitr.time</code> covers dates and clocks, <code>nitr.env</code> covers (filtered, read-only) environment access. If you add them, you have decided that your Lua is fully trusted.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">`exec_timeout_ms = 0` removes the CPU-exhaustion defense</p><p></p><p>A single infinite loop then holds one of your <code>workers</code> states forever, and enough of them stop the server entirely.</p></div><h2 id="a-production-checklist" tabindex="-1">A production checklist <a class="header-anchor" href="#a-production-checklist" aria-label="Permalink to “A production checklist”">​</a></h2><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h3><ul><li>[ ] <code>dev_mode = false</code> — it leaks source paths, line numbers and tracebacks to anyone who can cause an error. <code>nitr build</code> forces it off.</li><li>[ ] <code>[lua] exec_timeout_ms</code> and <code>memory_limit</code> left at sane values.</li><li>[ ] <code>[limits] max_body_bytes</code> sized for what you actually accept.</li><li>[ ] <code>[rate_limit] enabled = true</code>, especially in front of login and password-hashing endpoints.</li><li>[ ] <code>trust_request_id</code> and <code>[rate_limit] trust_forwarded_for</code> on <strong>only</strong> behind a proxy that sanitizes those headers.</li><li>[ ] <code>[cors] origins</code> explicit — never <code>[&quot;*&quot;]</code> together with <code>credentials</code> (the server refuses to start on that combination anyway).</li><li>[ ] <code>[fetch] allowed_hosts</code> set when any URL derives from user input.</li><li>[ ] <code>[std] features</code> listing only what you use — a builtin you do not enable is one a compromised script cannot reach.</li></ul><h3 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to “Secrets”">​</a></h3><ul><li>[ ] Not in <code>nitr.toml</code>, which is the file you commit.</li><li>[ ] Read once in <code>config.lua</code> via <code>nitr.env</code>, so a missing one fails at startup.</li><li>[ ] <code>[env] allow</code> scoped to the names your application needs.</li><li>[ ] Generated from a CSPRNG (<code>head -c 32 /dev/urandom | base64</code>).</li></ul><h3 id="application-code" tabindex="-1">Application code <a class="header-anchor" href="#application-code" aria-label="Permalink to “Application code”">​</a></h3><ul><li>[ ] All SQL parameterised — never string concatenation.</li><li>[ ] Every request body <a href="./validation">validated</a>; <code>check</code> strips undeclared fields, which is what prevents mass assignment.</li><li>[ ] Cookies <code>http_only</code>, <code>secure</code>, <code>same_site</code> set explicitly.</li><li>[ ] Secret comparisons via <code>nitr.crypto.constant_time_eq</code>.</li><li>[ ] Passwords through <code>nitr.crypto.password_hash</code>, never a bare hash.</li><li>[ ] <code>nitr.crypto.jwt.verify</code> always given an <code>algorithms</code> allow-list.</li><li>[ ] <a href="./cookies-sessions#csrf-protection">CSRF middleware</a> on cookie-authenticated form endpoints.</li><li>[ ] <code>| safe</code> in templates used only for markup you generated.</li><li>[ ] Upload filenames run through <code>nitr.path.basename</code>, or replaced with generated ones.</li><li>[ ] <code>on_error</code> returning a stable shape, never <code>err.message</code>.</li></ul><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to “Operations”">​</a></h3><ul><li>[ ] The static directory contains no <code>.env</code>, <code>.git</code> or backups — it is all public.</li><li>[ ] TLS terminated in front of Nitr (a proxy, a load balancer). Nitr does not terminate TLS itself.</li><li>[ ] Health probes on a separate <code>[health] bind</code> if the main listener is public.</li><li>[ ] <code>[log] format = &quot;json&quot;</code>, shipped somewhere, with alerts on <code>5xx</code> and <code>pool_checkout</code> sheds.</li><li>[ ] systemd hardening or a container with a read-only filesystem — see <a href="./deployment/">Deployment</a>.</li></ul><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p>Nitr does not terminate TLS. Put a reverse proxy or a load balancer in front of it — nginx, Caddy, HAProxy, or your cloud provider&#39;s — and let it own certificates, renewal and protocol configuration. That is one fewer thing in the process that runs your application code.</p><p>Behind such a proxy, remember to bind Nitr to a private address:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">listen = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:3000&quot;</span></span></code></pre></div><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Open a <a href="https://github.com/joseluisq/nitr/security/advisories/new" target="_blank" rel="noreferrer">private security advisory</a> rather than a public issue. See <a href="./../report-security-issues">Report Security Issues</a> for what makes a report actionable.</p>',30)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
